"""Invoice records."""


class Invoice:
    def __init__(self, client, due):
        self.client = client
        self.due = due

    def __repr__(self):
        return "Invoice(%r, %r)" % (self.client, self.due)


ROWS = [('ivory', 45), ('hale', 52), ('ivory', 33), ('ivory', 9), ('juno', 5), ('juno', 54), ('juno', 10)]


def load_invoices():
    """Yield the stored invoices one at a time."""
    for client, due in ROWS:
        yield Invoice(client, due)

