"""Share of the total due per invoice."""
from invoices import load_invoices


def due_shares(invoices):
    """Return each invoice's share of the total due, in order."""
    total = sum(x.due for x in invoices)
    return [x.due / total for x in invoices]


def stored_shares():
    """Shares for the stored invoices."""
    return due_shares(load_invoices())


def top_share(invoices):
    """Return the largest share, or 0.0 when there are no invoices."""
    shares = due_shares(invoices)
    return max(shares) if shares else 0.0


def describe_invoice(invoice):
    """Return a one-line description of a invoice."""
    return "%s: %s" % (invoice.client, invoice.due)


def client_names(invoices):
    """Return the distinct client values, in first-seen order."""
    names = []
    for x in invoices:
        if x.client not in names:
            names.append(x.client)
    return names

